using DocumentReader.Api.Configuration;
using DocumentReader.Api.Ingestion;
using DocumentReader.Api.Ingestion.Excel;
using DocumentReader.Tests.Infrastructure;
using Microsoft.Extensions.Logging.Abstractions;
using Microsoft.Extensions.Options;
using NPOI.HSSF.UserModel;
using NPOI.SS.UserModel;
using NPOI.SS.Util;

namespace DocumentReader.Tests.Ingestion.Excel;

/// <summary>Legacy .xls reading with real BIFF8 files generated by NPOI.</summary>
public sealed class XlsReaderTests
{
    private static readonly IOptions<LimitsOptions> Limits = Options.Create(new LimitsOptions());

    private readonly ExcelDocumentExtractor _extractor = new(
        new XlsxGridReader(Limits), new XlsGridReader(Limits), Limits, NullLogger<ExcelDocumentExtractor>.Instance);

    [Fact]
    public void Detect_NpoiWorkbook_IsXls()
    {
        Assert.Equal(FileType.Xls, FileTypeDetector.Detect(XlsFixtures.BillOfQuantities()));
    }

    [Fact]
    public void Read_LeadingEmptyRowsAndColumns_KeepExcelCoordinates()
    {
        var xls = XlsFixtures.Xls(workbook =>
        {
            var sheet = workbook.CreateSheet("Offset");
            XlsFixtures.Text(sheet, "C4", "Item");
            XlsFixtures.Number(sheet, "D7", 42);
        });

        var sheet = ReadSheet(xls);

        Assert.Equal("Item", sheet.GetCell(4, 3)?.DisplayText);
        Assert.Equal(42m, sheet.GetCell(7, 4)?.Number);
        Assert.Equal([4, 7], sheet.RowNumbers);
    }

    [Fact]
    public void Read_MergedCells_AreOneBased()
    {
        var xls = XlsFixtures.Xls(workbook =>
        {
            var sheet = workbook.CreateSheet("Merged");
            XlsFixtures.Text(sheet, "B2", "Title");
            sheet.AddMergedRegion(CellRangeAddress.ValueOf("B2:D3"));
        });

        Assert.Equal(new MergedRange(2, 2, 3, 4), Assert.Single(ReadSheet(xls).MergedRanges));
    }

    [Fact]
    public void Read_NumberFormatsAndDates_ArePreserved()
    {
        var xls = XlsFixtures.Xls(workbook =>
        {
            var sheet = workbook.CreateSheet("Values");
            var aed = workbook.CreateCellStyle();
            aed.DataFormat = workbook.CreateDataFormat().GetFormat("\"AED\" #,##0.00");
            XlsFixtures.Number(sheet, "A1", 1800.5, aed);
            var date = workbook.CreateCellStyle();
            date.DataFormat = HSSFDataFormat.GetBuiltinFormat("m/d/yy");
            var dateCell = XlsFixtures.Cell(sheet, "A2");
            dateCell.SetCellValue(new DateTime(2027, 3, 15));
            dateCell.CellStyle = date;
        });

        var sheet = ReadSheet(xls);

        var amount = sheet.GetCell(1, 1)!;
        Assert.Equal(1800.5m, amount.Number);
        Assert.Equal("AED", CurrencyDetector.FromNumberFormat(amount.NumberFormat));
        var due = sheet.GetCell(2, 1)!;
        Assert.Equal(CellValueKind.DateTime, due.Kind);
        Assert.Equal("2027-03-15", due.DisplayText);
    }

    [Fact]
    public void Read_StylesAreUnavailable_EvenForBoldCells()
    {
        var sheet = ReadSheet(XlsFixtures.BillOfQuantities());

        Assert.False(sheet.StylesAvailable);
        Assert.False(sheet.GetCell(3, 2)!.IsBold);
        Assert.Null(sheet.GetCell(5, 7)!.Formula);
    }

    [Fact]
    public void Extract_Xls_WarnsThatStylesAreUnavailable()
    {
        var result = _extractor.Extract(XlsFixtures.BillOfQuantities(), FileType.Xls, CancellationToken.None);

        Assert.Equal(DocumentStatus.Indexed, result.Status);
        Assert.Contains(result.Warnings, warning => warning.Contains("not available for .xls"));
    }

    [Fact]
    public void Extract_HiddenXlsSheet_IsIncludedWithWarning()
    {
        var xls = XlsFixtures.Xls(workbook =>
        {
            XlsFixtures.Text(workbook.CreateSheet("Visible"), "A1", "Shown");
            XlsFixtures.Text(workbook.CreateSheet("Secret"), "A1", "Hidden text");
            workbook.SetSheetVisibility(1, SheetVisibility.Hidden);
        });

        var result = _extractor.Extract(xls, FileType.Xls, CancellationToken.None);

        Assert.Contains(result.Warnings, warning => warning.Contains("\"Secret\" is hidden"));
    }

    [Fact]
    public void Extract_SameWorkbookAsXlsAndXlsx_DetectsSameTables()
    {
        var fromXls = _extractor.Extract(XlsFixtures.BillOfQuantities(), FileType.Xls, CancellationToken.None);
        var fromXlsx = _extractor.Extract(ExcelFixtures.BillOfQuantities(), FileType.Xlsx, CancellationToken.None);

        Assert.Equal(fromXlsx.Tables.Select(table => table.Range), fromXls.Tables.Select(table => table.Range));
        for (var index = 0; index < fromXlsx.Tables.Count; index++)
        {
            var expected = fromXlsx.Tables[index];
            var actual = fromXls.Tables[index];
            Assert.Equal(expected.Columns.Select(Describe), actual.Columns.Select(Describe));
            Assert.Equal(expected.Rows.Select(row => (row.RowNumber, row.Kind)), actual.Rows.Select(row => (row.RowNumber, row.Kind)));
        }

        Assert.Equal(fromXlsx.Chunks.Select(chunk => chunk.Text), fromXls.Chunks.Select(chunk => chunk.Text));
        Assert.Equal(fromXlsx.Chunks.Select(chunk => chunk.Source), fromXls.Chunks.Select(chunk => chunk.Source));
    }

    private static string Describe(TableColumn column) => $"{column.Letter}:{column.Name}:{column.Type}:{column.Currency}";

    private static SheetGrid ReadSheet(byte[] xls) =>
        new XlsGridReader(Limits).Read(xls, CancellationToken.None).Sheets[0];
}
